import{MOVEMENT_VISUALS}from'./movement-visuals.js';
import {configureFieldPersistence,completeFieldPreview} from './field-persistence.js';
import{gateLocal}from'./gate-cells.js';
import{HMS,LEDGES,addFieldObject,removeFieldObject,fieldObjects,fieldAt,canUseHM,ledgeAt}from'./field-model.js';
import{discoverFieldProfile,spritePixels}from'./field-profile.js';
import{setMovement,movementAt,portalAt}from'./world-model.js';
export function fieldWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={tab:'objects',kind:'strength',access:'standard',direction:'south',erase:false,paintArt:false,tileId:0};
 function profile(){const session=api.session();return session?discoverFieldProfile(session.reader):null;}
 function imageFor(kind){const s=api.session(),p=s&&profile();if(!p)return'field-'+kind;const id='field-'+s.id+'-'+kind;if(!api.asset(id)){const c=document.createElement('canvas');c.width=c.height=16;const ctx=c.getContext('2d'),im=ctx.createImageData(16,16);im.data.set(spritePixels(s.reader,p.sprites[HMS[kind].graphics]));ctx.putImageData(im,0,0);api.change(()=>{if(api.project().assets.length>=512)throw Error('This project has reached its image limit.');api.project().assets.push({id,name:HMS[kind].name,width:16,height:16,tileSize:16,data:c.toDataURL('image/png'),category:'Native HM objects'});});}return id;}
 function open(tab=state.tab){state.tab=tab;api.modal('HMs & ledges',`<div class="smart-tabs">${[['objects','Boulders & trees'],['ledges','Jump ledges'],['flash','Flash & darkness'],['test','Playtest']].map(([k,label])=>`<button type="button" data-field-tab="${k}" class="${k===tab?'active':''}">${label}</button>`).join('')}</div><div class="studio-actions"><button id="fieldGlobalRules" type="button">Global HM rules</button></div><div id="fieldContent"></div>`);document.querySelectorAll('[data-field-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.fieldTab;render();});$('#fieldGlobalRules').onclick=()=>api.globalHMs();render();}
 function render(){document.querySelectorAll('[data-field-tab]').forEach(b=>b.classList.toggle('active',b.dataset.fieldTab===state.tab));const t=$('#fieldContent'),map=api.map();if(state.tab==='objects'){
  t.innerHTML=`<p>Place actual game objects: push boulders after activating Strength, break rocks with Rock Smash, or clear Cut trees.</p><div class="smart-cards">${['strength','rocksmash','cut'].map(kind=>{const a=api.asset('field-'+kind);return`<article class="smart-card"><img class="smart-thumb" src="${esc(a.src||a.data)}" alt="${esc(HMS[kind].name)}"><strong>${HMS[kind].name}</strong><button type="button" data-field-kind="${kind}">Place</button></article>`;}).join('')}</div><div class="smart-actions"><button type="button" id="useOriginalHM">Use this map’s existing HM objects</button></div>${(map.fieldObjects||[]).map(o=>`<div class="world-row"><span><b>${esc(o.name)}</b><small>${o.x},${o.y} · ${o.access==='free'?'No HM requirements':'Global HM rules'}</small></span><button type="button" data-edit-field="${esc(o.id)}">Edit</button></div>`).join('')}<p class="hint-line">Objects reset on re-entry unless permanence is enabled. Permanent boulders are committed by a puzzle-completion scene. Standard activation follows Global HM rules in Game maker. Native defaults use the badge and taught move; puzzle mode always works. Export support is checked for compatible FireRed-family sources.</p>`;
  document.querySelectorAll('[data-field-kind]').forEach(b=>b.onclick=()=>{state.kind=b.dataset.fieldKind;api.mode('field');api.close();api.toast('Tap walkable ground to place '+HMS[state.kind].name+'.');});document.querySelectorAll('[data-edit-field]').forEach(b=>b.onclick=()=>edit(map.fieldObjects.find(o=>o.id===b.dataset.editField)));$('#useOriginalHM').onclick=convertOriginal;
 }else if(state.tab==='ledges'){
  const attrs=map.rom?.attributes||[],id=map.rom?.atlasId,art=id?attrs.map((a,i)=>({a,i})).filter(v=>(v.a&511)===LEDGES[state.direction].behavior):[];
  t.innerHTML=`<p>Choose the direction a player may jump, then drag along your ledge. Each jump crosses the ledge tile and lands one tile beyond it. Reverse approaches stay blocked.</p><div class="rule-presets">${Object.entries(LEDGES).map(([id,l])=>`<button type="button" data-ledge-direction="${id}" style="--rule:${MOVEMENT_VISUALS['ledge_'+id].color}" class="${state.direction===id?'active':''}"><span class="rule-icon" aria-hidden="true">${MOVEMENT_VISUALS['ledge_'+id].icon}</span>${l.name}</button>`).join('')}</div><label class="check"><input id="ledgePaintArt" type="checkbox" ${state.paintArt?'checked':''} ${!art.length?'disabled':''}> Paint native ledge art too</label>${art.length?`<label>Ledge appearance<select id="ledgeTile">${art.map((v,i)=>`<option value="${v.i}" ${state.tileId===v.i?'selected':''}>Native ledge style ${i+1}</option>`).join('')}</select></label><canvas id="ledgeArtPreview" width="64" height="64" class="ledge-art-preview"></canvas>`:'<p class="hint-line">Keep your existing artwork, or import a ROM map with matching ledge tiles to choose native art.</p>'}<div class="smart-actions"><button id="drawLedge" type="button" class="primary">Draw jump ledges</button><button id="eraseLedge" type="button">Erase jump rules</button></div><p class="hint-line">Arrows show jump direction while editing. Keep a clear landing tile and leave doors off the ledge.</p>`;
  document.querySelectorAll('[data-ledge-direction]').forEach(b=>b.onclick=()=>{state.direction=b.dataset.ledgeDirection;render();});$('#ledgePaintArt').onchange=e=>state.paintArt=e.target.checked;if(art.length){if(!art.some(a=>a.i===state.tileId))state.tileId=art[0].i;$('#ledgeTile').value=state.tileId;const preview=async()=>{const c=$('#ledgeArtPreview'),im=await api.ensureImage(id);if(!c?.isConnected)return;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,64,64);ctx.drawImage(im,state.tileId%16*16,Math.floor(state.tileId/16)*16,16,16,0,0,64,64);};$('#ledgeTile').onchange=e=>{state.tileId=+e.target.value;preview();};preview();}const begin=erase=>{state.erase=erase;api.world().state.overlay=true;api.mode('ledge');api.close();api.toast(erase?'Drag to remove jump rules; artwork stays.':'Drag along the ledge. Arrows show the allowed jump direction.');};$('#drawLedge').onclick=()=>begin(false);$('#eraseLedge').onclick=()=>begin(true);
 }else if(state.tab==='flash'){
  t.innerHTML=`<p>Make a cave dark, then add Flash to an interaction or a step-triggered event. Flash opens the light circle in the game and lights this map in Play check.</p><label class="check"><input id="darkMap" type="checkbox" ${(map.fieldSettings?.dark??map.rom?.dark)?'checked':''}> This map needs Flash</label><div class="smart-actions"><button id="saveDarkMap" type="button">Save lighting</button><button id="placeFlashEvent" type="button" class="primary">Place a Flash trigger</button></div><p class="hint-line">In Events, choose “HM / field action” to activate Strength, use Flash, or clear a selected rock/tree. Each action can require the normal HM and badge, or run freely for a puzzle or cutscene.</p>`;$('#saveDarkMap').onclick=()=>{api.change(()=>map.fieldSettings={dark:$('#darkMap').checked});api.refresh();api.toast('Map lighting saved.');};$('#placeFlashEvent').onclick=()=>{api.change(()=>map.fieldSettings={dark:$('#darkMap').checked});api.events().startHM('flash');};
 }else{
  t.innerHTML=`<p><b>Quick Play check</b> starts on your layout immediately. HM capabilities can be switched on/off to test your puzzle.</p><div class="field-capabilities">${Object.keys(HMS).map(k=>`<label class="check"><input type="checkbox" data-preview-hm="${k}" checked> ${k==='rocksmash'?'Rock Smash':k[0].toUpperCase()+k.slice(1)}</label>`).join('')}</div><label class="check"><input id="previewBadges" type="checkbox" checked> Player has the required badges</label><button id="startFieldPreview" type="button" class="primary">Start quick check</button><button id="startFieldInventory" type="button">Quick check with inventory & quest state</button><div class="divider"></div><p><b>Play the edited GBA</b> runs the actual game inside the app, with its real party, badge requirements and animations.</p><button id="startFieldROM" type="button">Compile & play ROM</button>`;$('#startFieldPreview').onclick=()=>{const moves=[...document.querySelectorAll('[data-preview-hm]:checked')].map(b=>b.dataset.previewHm),badges=$('#previewBadges').checked;api.close();api.world().startPlay();const p=api.world().state.play;if(p){p.hmMoves=new Set(moves);p.hmBadges=new Set(badges?[1,2,3,4,5,6,7,8]:[]);}};$('#startFieldInventory').onclick=()=>{$('#startFieldPreview').onclick();api.testState();};$('#startFieldROM').onclick=api.playROM;
 }}
 function edit(old=null,x=0,y=0){const kind=old?.kind||state.kind;api.modal(old?'Edit '+HMS[kind].name:'Place '+HMS[kind].name,`<label>Name<input id="fieldName" maxlength="100" value="${esc(old?.name||HMS[kind].name)}"></label><label>Activation<select id="fieldAccess"><option value="standard" ${(old?.access||state.access)==='standard'?'selected':''}>Use global HM rules</option><option value="free" ${(old?.access||state.access)==='free'?'selected':''}>Always works · puzzles and tests</option></select></label><label class="check"><input id="fieldPermanent" type="checkbox" ${old?.permanent?'checked':''}> Remember clearing / solved state</label>${kind==='strength'?`<div class="field-row"><label>Solved tile X<input id="fieldSolvedX" type="number" min="0" value="${old?.solvedPosition?.x??old?.x??x}"></label><label>Solved tile Y<input id="fieldSolvedY" type="number" min="0" value="${old?.solvedPosition?.y??old?.y??y}"></label></div><p class="hint-line">Add “Commit HM puzzle” after the scene’s solved conditions. Ordinary pushes remain temporary.</p>`:''}<div class="field-row"><label>Tile X<input id="fieldX" type="number" min="0" max="${api.map().width-1}" value="${old?.x??x}"></label><label>Tile Y<input id="fieldY" type="number" min="0" max="${api.map().height-1}" value="${old?.y??y}"></label></div><p>${kind==='strength'?'Face the boulder and press A to enable Strength, then walk into it to push. Pushing needs a clear tile behind it.':'Face the object and press A to clear it. It returns on map re-entry unless permanence is enabled.'}</p>${old?'<div class="smart-actions"><button id="duplicateField" type="button">Duplicate</button><button id="deleteField" type="button" class="danger">Remove object</button></div>':''}`,()=>{const nx=+$('#fieldX').value,ny=+$('#fieldY').value,map=api.map();if(!Number.isInteger(nx)||!Number.isInteger(ny)||nx<0||ny<0||nx>=map.width||ny>=map.height)throw Error('Choose a whole tile inside the map.');if((map.fieldObjects||[]).some(o=>o.id!==old?.id&&o.x===nx&&o.y===ny))throw Error('This tile already has an HM object.');if(portalAt(api.project(),map.id,nx,ny)||map.markers.some(n=>n.x===nx&&n.y===ny&&n.runtime))throw Error('Leave this tile clear of portals and authored events.');const floor=movementAt(map,nx,ny,{ignoreFieldObjects:true});if(floor.objectBlocked||map.wallCells?.[ny*map.width+nx]||map.gates?.some(g=>gateLocal(g,nx,ny)))throw Error('Choose open ground away from walls and solid objects.');const assetId=old?.assetId||imageFor(kind);api.change(()=>{if(old)Object.assign(old,{name:$('#fieldName').value.trim()||HMS[kind].name,x:nx,y:ny,access:$('#fieldAccess').value});else addFieldObject(map,kind,nx,ny,{name:$('#fieldName').value.trim(),assetId,access:$('#fieldAccess').value});const placed=old||map.fieldObjects.at(-1);configureFieldPersistence(api.project(),placed,$('#fieldPermanent').checked,kind==='strength'?{x:+$('#fieldSolvedX').value,y:+$('#fieldSolvedY').value}:{});setMovement(map,nx,ny,{mode:'walk',elevation:3});});api.refresh();},old?'Save object':'Place object');if(old){$('#duplicateField').onclick=()=>{state.kind=old.kind;state.access=old.access;api.mode('field');api.close();api.toast('Tap the duplicate’s new tile.');};$('#deleteField').onclick=()=>{api.change(()=>removeFieldObject(api.map(),old.id));api.close();api.refresh();};}}
 function convertOriginal(){try{const p=profile(),session=api.session(),map=api.map();if(!p||map.rom?.sourceId!==session?.id||map.rom.generated)throw Error('Open this imported map’s original ROM first.');const images=Object.fromEntries(['strength','rocksmash','cut'].map(k=>[k,imageFor(k)]));let count=0;api.change(()=>{for(const n of [...map.markers]){const kind=['strength','rocksmash','cut'].find(k=>HMS[k].graphics===n.rom?.sprite);if(!kind||n.runtime||n.rom?.script!==p.scripts[kind]?.address)continue;const assetId=images[kind];addFieldObject(map,kind,n.x,n.y,{name:HMS[kind].name,assetId,access:'standard',rom:{...n.rom}});map.markers=map.markers.filter(a=>a.id!==n.id);count++;}});api.refresh();api.toast(count?count+' original HM objects added to Play check.':'No untouched native HM objects found on this map.');open('objects');}catch(e){api.error(e);}}
 function paintLedge(x,y){const map=api.map();if(x<0||y<0||x>=map.width||y>=map.height)return;if(state.erase){if(map.movement?.[y*map.width+x]?.mode.startsWith('ledge_'))setMovement(map,x,y,{mode:'original'});return;}const d=LEDGES[state.direction];if(x+d.dx<0||y+d.dy<0||x+d.dx>=map.width||y+d.dy>=map.height||fieldAt(map,x,y)||portalAt(api.project(),map.id,x,y)||movementAt(map,x,y,{ignoreFieldObjects:true}).objectBlocked||map.wallCells?.[y*map.width+x]||map.gates?.some(g=>gateLocal(g,x,y))||movementAt(map,x+d.dx,y+d.dy).collision||portalAt(api.project(),map.id,x+d.dx,y+d.dy))return;setMovement(map,x,y,{mode:'ledge_'+state.direction,behavior:d.behavior,elevation:3});if(state.paintArt&&map.rom?.atlasId&&((map.rom.attributes[state.tileId]||0)&511)===d.behavior)map.layers.ground[y*map.width+x]={a:map.rom.atlasId,sx:state.tileId%16*16,sy:Math.floor(state.tileId/16)*16,size:16};}
 function draw(ctx,map){const play=api.world()?.state.play;for(const o of fieldObjects(map,play?.mapId===map.id?play:null)){const im=api.imageNow(o.assetId);if(im)ctx.drawImage(im,o.x*16,o.y*16,16,16);}if(!play&&(api.tool()==='ledge'||api.world()?.state.overlay)){ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 12px sans-serif';for(let y=0;y<map.height;y++)for(let x=0;x<map.width;x++){const d=ledgeAt(map,x,y);if(d){ctx.fillStyle='#f6b866';ctx.fillRect(x*16+2,y*16+2,12,12);ctx.fillStyle='#43250c';ctx.fillText({south:'↓',north:'↑',east:'→',west:'←'}[d],x*16+8,y*16+8);}}ctx.restore();}}
 function darkness(ctx,map){const p=api.world().state.play;if(!p||!(map.fieldSettings?.dark??map.rom?.dark)||p.litMaps.has(map.id))return;ctx.save();const x=(p.x+.5)*16,y=(p.y+.5)*16;ctx.fillStyle='#061013e8';ctx.beginPath();ctx.rect(0,0,map.width*16,map.height*16);ctx.arc(x,y,42,0,Math.PI*2,true);ctx.fill('evenodd');ctx.restore();}
 function previewAction(effect,targetId,requireHM=false){const p=api.world().state.play;if(!p)return;if(requireHM&&!canUseHM(effect,p,'standard',api.project()))throw Error('This test player needs the matching HM and badge.');if(effect==='flash'){p.flash=true;p.litMaps.add(api.map().id);}else if(effect==='strength')p.strength=true;else{const o=(api.map().fieldObjects||[]).find(o=>o.id===targetId&&o.kind===effect);if(!o)throw Error('The target rock or tree is missing.');p.removedField.add(o.id);if(o.permanent)completeFieldPreview(o,p);}api.refresh();}
 return{state,open,edit,profile,paintLedge,draw,darkness,previewAction,tap:(x,y)=>edit(fieldAt(api.map(),x,y)||null,x,y)};
}
